const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

const parseJson = async (response) => {
  const text = await response.text();
  return text ? JSON.parse(text) : {};
};

const request = async (path, options = {}) => {
  const response = await fetch(`${API_BASE_URL}${path}`, options);
  const data = await parseJson(response);

  if (!response.ok) {
    throw new Error(data.message || data.error || "Backend request failed");
  }

  return data;
};

export const analyzeCxr = (payload) => {
  const body = new FormData();

  Object.entries(payload).forEach(([key, value]) => {
    if (value !== undefined && value !== null) {
      body.append(key, value);
    }
  });

  return request("/analyze_cxr", {
    method: "POST",
    body
  });
};

export const getPatients = () => request("/patients");

export const requestRadiologistReview = (patientId) =>
  request("/feedback", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      patientId,
      type: "radiologist_review_requested",
      status: "pending_consultation"
    })
  });

export const submitRadiologistFeedback = (payload) =>
  request("/feedback", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify(payload)
  });
